main <- function() {
  ROOT <- normalizePath(getwd(), winslash = "/", mustWork = TRUE)
  if (!file.exists(file.path(ROOT, "HairRegeneration_AI.Rproj"))) {
    stop("请先在 RStudio 打开 HairRegeneration_AI.Rproj，然后在项目根目录运行。")
  }
  if (Sys.info()[["sysname"]] != "Darwin" || !capabilities("aqua")) {
    stop("本脚本使用你已成功运行的 macOS Quartz 输出 PNG/TIFF；请在 Mac RStudio 中运行。")
  }
  
  # Recover exactly the user-supplied CSV from within this script.
  pos <- seq.int(1L, nchar(DATA_GZ_HEX), by = 2L)
  gzip_bytes <- as.raw(strtoi(substring(DATA_GZ_HEX, pos, pos + 1L), base = 16L))
  csv_bytes <- memDecompress(gzip_bytes, type = "gzip", asChar = FALSE)
  if (length(csv_bytes) != 1555453L) stop("内置 CSV 解压字节数不符，脚本内容可能不完整。")
  D <- utils::read.csv(text = rawToChar(csv_bytes), check.names = FALSE,
                       stringsAsFactors = FALSE)
  needed <- c("GeneSymbol", "X_Intact_minus_P3_2D_log2FC",
              "Y_P3_3D_minus_P3_2D_log2FC", "PlotClass",
              "Directional_rescue", "Strict_rescue")
  if (!identical(names(D), needed)) stop("内置 CSV 列名或顺序异常，已停止绘图。")
  if (nrow(D) != 21355L) stop("内置 CSV 行数不符。")
  classes <- names(COL)
  counts <- table(factor(D$PlotClass, levels = classes))
  if (anyNA(D$PlotClass) || !identical(as.integer(counts),
                                       c(16360L, 3424L, 510L, 1061L))) stop("原始基因分类计数不符。")
  if (!is.logical(D$Directional_rescue) || !is.logical(D$Strict_rescue) ||
      anyNA(D$Directional_rescue) || anyNA(D$Strict_rescue) ||
      sum(D$Directional_rescue) != 4995L || sum(D$Strict_rescue) != 1571L) {
    stop("内置 rescue flags 与历史审计不一致。")
  }
  X <- D[[needed[2L]]]
  Y <- D[[needed[3L]]]
  if (!is.numeric(X) || !is.numeric(Y) || any(!is.finite(X)) || any(!is.finite(Y))) {
    stop("内置真实数据的 X/Y 坐标异常。")
  }
  if (any(X < X_LIM[1] | X > X_LIM[2] | Y < Y_LIM[1] | Y > Y_LIM[2])) {
    stop("当前坐标范围会裁掉真实基因点；已停止，需先调整 X_LIM/Y_LIM。")
  }
  
  out_parent <- file.path(ROOT, "figures", "FIGURE 1")
  OUT <- file.path(out_parent, "Panel_D_Nature_final")
  if (file.exists(OUT) || dir.exists(OUT)) stop("输出目录已存在，保护旧版本：", OUT)
  if (!dir.exists(out_parent)) dir.create(out_parent, recursive = TRUE)
  stage <- tempfile(pattern = ".Panel_D_v24_staging_", tmpdir = out_parent)
  if (!dir.create(stage)) stop("无法创建临时导出文件夹：", stage)
  complete <- FALSE
  on.exit({
    if (!complete && dir.exists(stage)) unlink(stage, recursive = TRUE)
  }, add = TRUE)
  
  base <- "Fig1_Panel_D_v24"
  pdf_path <- file.path(stage, paste0(base, ".pdf"))
  png_path <- file.path(stage, paste0(base, ".png"))
  tif_path <- file.path(stage, paste0(base, ".tif"))
  csv_path <- file.path(stage, "plot_data.csv")
  txt_path <- file.path(stage, "SOURCE_AUDIT.txt")
  
  # Store original bytes (not a reserialized or renamed dataframe).
  con <- file(csv_path, open = "wb")
  tryCatch(writeBin(csv_bytes, con), finally = close(con))
  got_md5 <- unname(tools::md5sum(csv_path))
  expected_md5 <- "421002592fa7d864d81010e0d813e8dc"
  if (!identical(got_md5, expected_md5)) {
    stop("CSV MD5 校验失败：禁止输出与上传数据不一致的图。")
  }
  
  mm <- function(x) grid::unit(x, "mm")
  at_x <- function(x) PLOT_LEFT_MM + (x - X_LIM[1L]) / diff(X_LIM) *
    (PLOT_RIGHT_MM - PLOT_LEFT_MM)
  at_y <- function(y) PLOT_BOTTOM_MM + (y - Y_LIM[1L]) / diff(Y_LIM) *
    (PLOT_TOP_MM - PLOT_BOTTOM_MM)
  put_text <- function(value, x, y, pt, color = INK, rot = 0,
                       just = "centre") {
    grid::grid.text(value, x = mm(x), y = mm(y), rot = rot, just = just,
                    gp = grid::gpar(col = color, fontfamily = FONT, fontsize = pt))
  }
  put_line <- function(x0, y0, x1, y1, col = AXIS, lwd = 0.70, lty = 1) {
    grid::grid.lines(x = mm(c(x0, x1)), y = mm(c(y0, y1)),
                     gp = grid::gpar(col = col, lwd = lwd, lty = lty))
  }
  
  draw_panel <- function() {
    grid::grid.newpage()
    grid::pushViewport(grid::viewport(x = mm(0), y = mm(0),
                                      width = mm(WIDTH_MM), height = mm(HEIGHT_MM),
                                      just = c("left", "bottom")))
    
    # Validate actual legend text width using current graphics-device font metrics.
    labels <- c("Other (16,360)", "Directional only (3,424)",
                "Strict upward (510)", "Strict downward (1,061)")
    for (label in labels) {
      g <- grid::textGrob(label, gp = grid::gpar(fontfamily = FONT,
                                                 fontsize = LEGEND_PT))
      text_width <- grid::convertWidth(grid::grobWidth(g),
                                       unitTo = "mm", valueOnly = TRUE)
      if (LEGEND_TEXT_MM + text_width > WIDTH_MM - 1.0) {
        stop(sprintf("图例可能被裁切：%s；文字宽 %.2f mm", label, text_width))
      }
    }
    
    # Scatter viewport: always clip points/lines strictly to its own axes.
    grid::pushViewport(grid::viewport(
      x = mm(PLOT_LEFT_MM), y = mm(PLOT_BOTTOM_MM),
      width = mm(PLOT_RIGHT_MM - PLOT_LEFT_MM),
      height = mm(PLOT_TOP_MM - PLOT_BOTTOM_MM),
      just = c("left", "bottom"), xscale = X_LIM, yscale = Y_LIM,
      clip = "on"))
    grid::grid.lines(x = grid::unit(X_LIM, "native"),
                     y = grid::unit(c(0, 0), "native"),
                     gp = grid::gpar(col = ZERO, lwd = 0.55))
    grid::grid.lines(x = grid::unit(c(0, 0), "native"),
                     y = grid::unit(Y_LIM, "native"),
                     gp = grid::gpar(col = ZERO, lwd = 0.55))
    grid::grid.lines(x = grid::unit(c(-8, 8), "native"),
                     y = grid::unit(c(-8, 8), "native"),
                     gp = grid::gpar(col = DIAG, lwd = 0.65, lty = "44"))
    
    for (cl in classes) {
      sel <- which(D$PlotClass == cl)
      point_mm <- switch(cl, "Other genes" = 0.125,
                         "Directional only" = 0.170,
                         "Strict upward" = 0.245,
                         "Strict downward" = 0.245)
      alpha <- switch(cl, "Other genes" = 0.21,
                      "Directional only" = 0.55,
                      "Strict upward" = 0.89,
                      "Strict downward" = 0.89)
      grid::grid.points(x = grid::unit(X[sel], "native"),
                        y = grid::unit(Y[sel], "native"), pch = 16,
                        size = mm(point_mm),
                        gp = grid::gpar(col = grDevices::adjustcolor(COL[[cl]], alpha.f = alpha)))
    }
    grid::popViewport()
    
    # Axes and labels are placed in independent millimetre coordinates.
    put_line(PLOT_LEFT_MM, PLOT_BOTTOM_MM, PLOT_RIGHT_MM, PLOT_BOTTOM_MM,
             lwd = 0.62)
    put_line(PLOT_LEFT_MM, PLOT_BOTTOM_MM, PLOT_LEFT_MM, PLOT_TOP_MM,
             lwd = 0.62)
    for (v in TICKS) {
      put_line(at_x(v), PLOT_BOTTOM_MM, at_x(v), PLOT_BOTTOM_MM - 0.95,
               lwd = 0.45)
      put_text(as.character(v), at_x(v), PLOT_BOTTOM_MM - 2.75,
               AXIS_TICK_PT, color = MUTED)
      put_line(PLOT_LEFT_MM - 0.95, at_y(v), PLOT_LEFT_MM, at_y(v),
               lwd = 0.45)
      put_text(as.character(v), PLOT_LEFT_MM - 1.9, at_y(v),
               AXIS_TICK_PT, color = MUTED, just = "right")
    }
    put_text("Intact DP - P3 2D (log2FC)",
             (PLOT_LEFT_MM + PLOT_RIGHT_MM)/2, 4.5, AXIS_TITLE_PT)
    put_text("P3 3D - P3 2D (log2FC)", 2.5,
             (PLOT_BOTTOM_MM + PLOT_TOP_MM)/2, AXIS_TITLE_PT, rot = 90)
    put_text("y = x", at_x(6.05), at_y(7.10), ANNOTATION_PT,
             color = MUTED, just = "right")
    
    # Precisely placed, never rotated: one column, four horizontal rows.
    for (i in seq_along(labels)) {
      grid::grid.points(x = mm(LEGEND_DOT_MM), y = mm(LEGEND_Y_MM[i]),
                        pch = 16, size = mm(0.70), gp = grid::gpar(col = COL[[classes[i]]]))
      put_text(labels[i], LEGEND_TEXT_MM, LEGEND_Y_MM[i],
               LEGEND_PT, color = MUTED, just = "left")
    }
    grid::popViewport()
  }
  
  W <- WIDTH_MM / 25.4
  H <- HEIGHT_MM / 25.4
  render <- function(file_path, kind) {
    if (kind == "pdf") {
      grDevices::pdf(file_path, width = W, height = H,
                     family = FONT, useDingbats = FALSE, onefile = FALSE, bg = "white")
    } else if (kind == "png") {
      grDevices::quartz(type = "png", file = file_path,
                        width = W, height = H, dpi = DPI, bg = "white")
    } else if (kind == "tif") {
      grDevices::quartz(type = "tiff", file = file_path,
                        width = W, height = H, dpi = DPI, bg = "white")
    } else stop("Unexpected device type")
    tryCatch(draw_panel(), finally = grDevices::dev.off())
    if (!file.exists(file_path) || is.na(file.info(file_path)$size) ||
        file.info(file_path)$size < 1000L) {
      stop("输出图形文件不存在或损坏：", file_path)
    }
  }
  
  render(pdf_path, "pdf")
  render(png_path, "png")
  render(tif_path, "tif")
  
  writeLines(c(
    "Figure 1 | Panel D | v24 | final 88 mm print-size",
    "Source: uploaded plot_data.csv; compressed and embedded losslessly in script",
    paste("Original CSV MD5:", got_md5),
    "Original CSV SHA256: 041a047c2e86ed2eff8528a8dec5854d967a609269c28b49f3a2f60086a99218",
    paste("Rows:", nrow(D)),
    paste(names(counts), as.integer(counts), sep = ": "),
    paste("Directional_rescue TRUE:", sum(D$Directional_rescue)),
    paste("Strict_rescue TRUE:", sum(D$Strict_rescue)),
    "X = X_Intact_minus_P3_2D_log2FC",
    "Y = Y_P3_3D_minus_P3_2D_log2FC",
    paste("Size (mm):", WIDTH_MM, "x", HEIGHT_MM, "; raster DPI:", DPI),
    "This panel was designed at approximately final placed width; place at 88 mm in Figure 1 without downscaling.",
    paste("Axes title pt:", AXIS_TITLE_PT, "tick pt:", AXIS_TICK_PT, "legend pt:", LEGEND_PT),
    "Independent plotting of supplied real data; no new labels or experimental analysis.",
    "Five outputs: PDF (vector), PNG (600 dpi), TIFF (600 dpi), original CSV, audit TXT"
  ), txt_path, useBytes = TRUE)
  
  expected <- c(paste0(base, c(".pdf", ".png", ".tif")),
                "plot_data.csv", "SOURCE_AUDIT.txt")
  if (length(list.files(stage)) != 5L ||
      !all(file.exists(file.path(stage, expected)))) {
    stop("未形成预期的五个文件，已终止并清理临时输出。")
  }
  if (file.exists(OUT) || dir.exists(OUT)) stop("输出目录运行中已存在，拒绝覆盖：", OUT)
  if (!file.rename(stage, OUT)) stop("完成生成，但无法将暂存目录移动到目标目录。")
  complete <- TRUE
  message("SUCCESS - Five files, no old data overwritten:\n",
          paste(file.path(OUT, expected), collapse = "\n"))
  invisible(OUT)
}

main()
